import{_ as e}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as o,o as r,ag as a}from"./chunks/mermaid.Bf0DxEx6.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const g=JSON.parse(`{"title":"NetEase UU Remote learning map","description":"NetEase UU Remote is NetEase's remote control software. It takes the screen streaming route: install the client on both ends, then connect by signing in to the same account or by passing on a device ID and verification code. This page is the product overview plus a decision table. It first answers 'which one should I install, and when should I use it', then hands you to the tutorial.","frontmatter":{"title":"NetEase UU Remote learning map","description":"NetEase UU Remote is NetEase's remote control software. It takes the screen streaming route: install the client on both ends, then connect by signing in to the same account or by passing on a device ID and verification code. This page is the product overview plus a decision table. It first answers 'which one should I install, and when should I use it', then hands you to the tutorial.","domain":"product","tags":["remote-control","remote-desktop","netease"],"role":"map"},"headers":[],"relativePath":"products/uu-remote/index.md","filePath":"products/uu-remote/index.md","lastUpdated":1795792629000}`),n={name:"products/uu-remote/index.md"};function i(s,t,l,d,h,c){return r(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="netease-uu-remote-learning-map" tabindex="-1">NetEase UU Remote learning map <a class="header-anchor" href="#netease-uu-remote-learning-map" aria-label="Permalink to &quot;NetEase UU Remote learning map&quot;">​</a></h1><blockquote><p><strong>网易UU远程</strong> (NetEase UU Remote) is NetEase&#39;s remote control software. It lets you operate your own computer while you are away from it, or fix someone else&#39;s computer. It takes the &quot;screen streaming&quot; route: install the client on both ends, then sign in to the same account or pass on a &quot;device ID + verification code&quot;, and the desktop of the other device appears in front of you.</p><p>This page is the <strong>product overview + decision table</strong>. Installation and daily use are both in the <a href="./uu-remote.html">tutorial</a>. UI text and numbers come from official NetEase pages opened on 2026-11-24. Interface labels are the English interface text of the Windows client, version 4.48; the phone apps and the system dialogs of macOS may word things differently.</p></blockquote><h2 id="audience-prerequisites-non-goals" tabindex="-1">Audience / prerequisites / non-goals <a class="header-anchor" href="#audience-prerequisites-non-goals" aria-label="Permalink to &quot;Audience / prerequisites / non-goals&quot;">​</a></h2><ul><li><strong>Who</strong>: people who write frontend code and have used a command line, but have never touched remote control software.</li><li><strong>Prerequisites</strong>: two internet-connected devices and a UU Remote account. For the system requirements of each platform, see the &quot;Install&quot; section of the tutorial.</li><li><strong>Non-goals</strong>: <ul><li>No internals. The vendor has not published the connection setup, codecs, protocol or server architecture.</li><li>No UU加速器 (UU game accelerator), MuMu模拟器 (MuMu Emulator) or 网易千千壁纸 (NetEase Qianqian Wallpaper). They are only products listed under &quot;Friendly links&quot; on the official site.</li><li>No deep dive into &quot;cloud devices&quot; (game cloud PC, AI cloud PC). They are another group of products in the official site&#39;s navigation.</li><li>No feature or price comparison with other remote control software. This page did not open their official sites.</li></ul></li></ul><h2 id="product-family" tabindex="-1">Product family <a class="header-anchor" href="#product-family" aria-label="Permalink to &quot;Product family&quot;">​</a></h2><p>The &quot;official names&quot; in the table below are copied from official pages opened on 2026-11-24. This directory has <strong>only one tutorial</strong>; every other item takes one row on the map.</p><table tabindex="0"><thead><tr><th>Official name</th><th>Official URL</th><th>On this site</th></tr></thead><tbody><tr><td><strong>Windows 版客户端</strong> (Windows client)</td><td><a href="https://uuyc.163.com/download/" target="_blank" rel="noreferrer">Download page</a> · <a href="https://uuyc.163.com/" target="_blank" rel="noreferrer">Official home page</a></td><td>Standalone page: <a href="./uu-remote.html">tutorial</a></td></tr><tr><td><strong>macOS 版客户端</strong> (macOS client; works both as controller and as controlled computer)</td><td>Download page · <a href="https://uuyc.163.com/features/mac/" target="_blank" rel="noreferrer">Control a Mac remotely</a> · <a href="https://uuyc.163.com/help/macos.html" target="_blank" rel="noreferrer">How to control a Mac</a></td><td>Tutorial section: making a Mac controllable, under Install</td></tr><tr><td><strong>iOS 版客户端</strong> (iOS client; listed in the App Store as &quot;UU远程-流畅可靠，就是好用！&quot;, that is &quot;UU Remote: smooth, reliable, simply easy to use&quot;; seller Guangzhou NetEase Computer System Co.Ltd)</td><td><a href="https://apps.apple.com/cn/app/id1642306791" target="_blank" rel="noreferrer">App Store</a> · Download page</td><td>Tutorial section: controlling a computer from a phone</td></tr><tr><td><strong>Android 版客户端</strong> (Android client)</td><td><a href="https://uuyc.163.com/download/" target="_blank" rel="noreferrer">Download page</a></td><td>Tutorial section: controlling a computer from a phone</td></tr><tr><td><strong>Android TV 版客户端</strong> (Android TV client; the official site also calls it the TV edition; controller only, and it connects only to Windows)</td><td>Download page · <a href="https://uuyc.163.com/features/tv/" target="_blank" rel="noreferrer">Play on the living room TV</a> · <a href="https://uuyc.163.com/help/20250117/40220_1207352.html" target="_blank" rel="noreferrer">TV usage tutorial</a></td><td>One row on the map</td></tr><tr><td><strong>UU远程精简版</strong> (UU Remote Lite; the controlled computer for remote assistance, Windows only, no install and no sign-in)</td><td><a href="https://uuyc.163.com/features/sos/" target="_blank" rel="noreferrer">Lite edition page</a> · <a href="https://uuyc.163.com/help/green.html" target="_blank" rel="noreferrer">Usage tutorial</a></td><td>Tutorial section: giving someone remote assistance</td></tr><tr><td><strong>UU远程运维版</strong> (UU Remote Ops edition; bulk deployment in server rooms, with a command line)</td><td><a href="https://uuyc.163.com/help/cmd.html" target="_blank" rel="noreferrer">Command line tutorial</a> · <a href="https://uuyc.163.com/help/ops.html" target="_blank" rel="noreferrer">Build tutorial</a></td><td>One row on the map</td></tr><tr><td><strong>uuyc-cli</strong> (official command line tool)</td><td><a href="https://uuyc.163.com/help/cli.html" target="_blank" rel="noreferrer">CLI tutorial</a></td><td>Tutorial section: official CLI</td></tr><tr><td><strong>VIP 会员、全球 VIP 会员</strong> (VIP membership and Global VIP membership)</td><td><a href="https://uuyc.163.com/help/membership.html" target="_blank" rel="noreferrer">Membership benefits</a> · <a href="https://uuyc.163.com/help/service-agreement.html" target="_blank" rel="noreferrer">Membership service agreement</a></td><td>Tutorial section: pricing</td></tr><tr><td><strong>UU远程 Linux PC 端</strong> (UU Remote for Linux PC; in beta, supports both the controller and the controlled role)</td><td><a href="https://uuyc.163.com/help/linux_test.html" target="_blank" rel="noreferrer">Linux beta FAQ</a></td><td>One row on the map: in beta</td></tr><tr><td><strong>UU远程 HarmonyOS 移动端</strong> (UU Remote for HarmonyOS mobile; in beta, controller only)</td><td><a href="https://uuyc.163.com/help/harmonyos_test.html" target="_blank" rel="noreferrer">HarmonyOS beta FAQ</a></td><td>One row on the map: in beta</td></tr><tr><td><strong>掌机</strong> (handheld consoles)</td><td>The positioning copy on the official home page mentions handheld consoles; the download page has no handheld client entry</td><td>One row on the map: go by the official site</td></tr><tr><td><strong>云设备</strong> (cloud devices: game cloud PC, AI cloud PC, cloud drive)</td><td>The &quot;cloud devices&quot; group in the official site&#39;s navigation · <a href="https://uuyc.163.com/help/20260422/42867_1297276.html" target="_blank" rel="noreferrer">How to use the cloud drive</a></td><td>One row on the map: not this product</td></tr></tbody></table><h3 id="names-that-collide" tabindex="-1">Names that collide <a class="header-anchor" href="#names-that-collide" aria-label="Permalink to &quot;Names that collide&quot;">​</a></h3><ul><li><strong>UU Remote ≠ UU加速器.</strong> UU加速器 is a game accelerator. It sits under &quot;Friendly links&quot; on the official site and is unrelated to this product. One confusing spot: in the official router documentation, when a router acts as the &quot;power-on helper device&quot; for UU Remote, the plugin it installs is called &quot;网易UU加速器插件 WOL 版本&quot; (NetEase UU Accelerator plugin, WOL edition).</li><li><strong>UU Remote ≠ MuMu模拟器, 网易千千壁纸.</strong> They are listed under &quot;Friendly links&quot; too.</li><li><strong>&quot;GameViewer远程&quot; is the old name.</strong> The official announcement page (page dated 2024-12-10) states that &quot;GameViewer远程&quot; was officially renamed &quot;网易UU远程&quot;. See the <a href="https://uuyc.163.com/blog/20241206/41377_1198665.html" target="_blank" rel="noreferrer">official announcement</a>.</li><li><strong>StarDesk is the name of the overseas edition.</strong> The same software is released outside China as StarDesk, with its own <a href="https://www.stardesk.net" target="_blank" rel="noreferrer">website</a> and <a href="https://apps.apple.com/us/app/id6751540294" target="_blank" rel="noreferrer">App Store app</a> (the developer listed on the store is GearUP Portal Pte. Ltd.; released on 2025-09-28). The English interface text of the China edition&#39;s Windows client mostly uses this name too. The two editions have their own websites, downloads and pricing; this directory covers the China edition only.</li><li><strong>VIP ≠ Global VIP.</strong> Global VIP adds one benefit: &quot;global remote control nodes&quot;. The official FAQ states that UU Remote prompts you to buy Global VIP when the controlled computer is overseas, or when the controller has a VPN on and is identified as overseas. For prices and benefits, see the &quot;Pricing&quot; section of the tutorial.</li><li><strong>The security password is not the connection password.</strong> It locks the client; connections rely on the verification code.</li><li><strong>Android screen sharing is not remote control of an Android phone.</strong> The other side can only watch, listen and annotate, not operate.</li></ul><h3 id="checking-the-official-top-level-navigation" tabindex="-1">Checking the official top-level navigation <a class="header-anchor" href="#checking-the-official-top-level-navigation" aria-label="Permalink to &quot;Checking the official top-level navigation&quot;">​</a></h3><p>The two-level navigation of the official home page is below. Every item has somewhere to go.</p><table tabindex="0"><thead><tr><th>Use case (official name)</th><th>Official URL</th><th>In one line</th></tr></thead><tbody><tr><td><strong>远程办公</strong> (remote work)</td><td><a href="https://uuyc.163.com/features/work/" target="_blank" rel="noreferrer">features/work</a></td><td>Reach back to your own workstation while developing, designing or editing</td></tr><tr><td><strong>远程游戏</strong> (remote gaming)</td><td><a href="https://uuyc.163.com/games/" target="_blank" rel="noreferrer">games</a></td><td>Play PC games from a phone, tablet or TV</td></tr><tr><td><strong>Remote Assistance</strong></td><td><a href="https://uuyc.163.com/features/support/" target="_blank" rel="noreferrer">features/support</a></td><td>Help someone fix their computer with the device ID and verification code they pass on</td></tr><tr><td><strong>客厅畅玩</strong> (living room play)</td><td><a href="https://uuyc.163.com/features/tv/" target="_blank" rel="noreferrer">features/tv</a></td><td>Control a computer from the TV edition</td></tr><tr><td><strong>Mac 电脑被控</strong> (Mac as the controlled computer)</td><td><a href="https://uuyc.163.com/features/mac/" target="_blank" rel="noreferrer">features/mac</a></td><td>Control a Mac from several kinds of devices</td></tr></tbody></table><table tabindex="0"><thead><tr><th>Feature (official name)</th><th>Official URL</th><th>Where in the tutorial</th></tr></thead><tbody><tr><td><strong>File Transfer</strong></td><td><a href="https://uuyc.163.com/features/file/" target="_blank" rel="noreferrer">features/file</a></td><td>Transfer files, sync the clipboard, send audio</td></tr><tr><td><strong>高清画面</strong> (HD picture)</td><td><a href="https://uuyc.163.com/features/color/" target="_blank" rel="noreferrer">features/color</a></td><td>Adjust picture quality, frame rate and resolution</td></tr><tr><td><strong>隐私防护</strong> (privacy protection)</td><td><a href="https://uuyc.163.com/features/privacy/" target="_blank" rel="noreferrer">features/privacy</a></td><td>Turn on privacy mode in a meeting room or a public place</td></tr><tr><td><strong>多屏协作</strong> (multi-screen collaboration)</td><td><a href="https://uuyc.163.com/features/device/" target="_blank" rel="noreferrer">features/device</a></td><td>Watch several screens or several devices at once</td></tr><tr><td><strong>远程开机</strong> (remote wake-up)</td><td><a href="https://uuyc.163.com/features/wol/" target="_blank" rel="noreferrer">features/wol</a></td><td>Remote wake-up</td></tr><tr><td><strong>按键映射</strong> (key mapping)</td><td><a href="https://uuyc.163.com/features/keyboard/" target="_blank" rel="noreferrer">features/keyboard</a></td><td>Playing games</td></tr><tr><td><strong>Wireless Secondary Screen</strong></td><td><a href="https://uuyc.163.com/features/wireless-screen/" target="_blank" rel="noreferrer">features/wireless-screen</a></td><td>Use a tablet or phone as a wireless secondary display</td></tr></tbody></table><h2 id="what-problem-it-solves" tabindex="-1">What problem it solves <a class="header-anchor" href="#what-problem-it-solves" aria-label="Permalink to &quot;What problem it solves&quot;">​</a></h2><h3 id="without-it-vs-with-it" tabindex="-1">Without it vs with it <a class="header-anchor" href="#without-it-vs-with-it" aria-label="Permalink to &quot;Without it vs with it&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Scenario</th><th>Without remote control</th><th>With UU Remote</th></tr></thead><tbody><tr><td>A file is stuck on your home computer, which is powered off</td><td>You have to go back, turn it on and get the file</td><td>Wake the computer up remotely, then get the file with file transfer (the wake-up conditions must be configured beforehand)</td></tr><tr><td>Your parents&#39; computer has a problem and you are in another city</td><td>You guide them step by step over the phone</td><td>Your parents pass on the device ID and a verification code, and you operate directly</td></tr><tr><td>Your home computer is running a build or an agent</td><td>Someone has to sit at it</td><td>Check progress and type the next step from your phone; after the terminal session disconnects, you can reattach</td></tr><tr><td>You want the computer&#39;s picture on a big screen</td><td>Move the computer next to the TV</td><td>Control it from the TV edition, or attach a tablet as a wireless secondary display</td></tr></tbody></table><h3 id="compared-with-the-alternatives" tabindex="-1">Compared with the alternatives <a class="header-anchor" href="#compared-with-the-alternatives" aria-label="Permalink to &quot;Compared with the alternatives&quot;">​</a></h3><p>Only what this page can verify is listed.</p><table tabindex="0"><thead><tr><th>Option</th><th>How it connects</th><th>Who it suits</th><th>On this site</th></tr></thead><tbody><tr><td>UU Remote</td><td><strong>Screen streaming</strong>: install the client on both ends, then sign in to the same account or pass on a device ID and a verification code</td><td>People who want it to work straight after installing and do not want to configure networking themselves</td><td>This directory</td></tr><tr><td>Tailscale plus the system&#39;s built-in remote desktop</td><td>First put the devices into one private network at the <strong>network layer</strong>, then connect with the remote desktop built into the system</td><td>People who are willing to configure things themselves and want to use the system&#39;s remote desktop</td><td><a href="./../tailscale/">Tailscale</a></td></tr><tr><td>Cindy</td><td>Has a built-in phone remote desktop feature</td><td>People who want to handle the phone side in the same tool</td><td><a href="./../cindy/">Cindy</a></td></tr><tr><td>Other remote control software (ToDesk, 向日葵 (Sunlogin), RustDesk, etc.)</td><td>This page did not check their official sites, so there is no comparison</td><td>None</td><td>None</td></tr></tbody></table><h2 id="quick-decisions" tabindex="-1">Quick decisions <a class="header-anchor" href="#quick-decisions" aria-label="Permalink to &quot;Quick decisions&quot;">​</a></h2><table tabindex="0"><thead><tr><th>My situation</th><th>What to use</th></tr></thead><tbody><tr><td>Fixing a colleague&#39;s or a parent&#39;s computer problem once</td><td>Remote assistance: the other side passes on a &quot;device ID + temporary verification code&quot;</td></tr><tr><td>The other side has no client and does not want one</td><td>Send them <a href="https://uuyc.163.com/features/sos/" target="_blank" rel="noreferrer">UU Remote Lite</a>; Windows controlled computers only</td></tr><tr><td>Your own computer, and you want to connect at any time</td><td>Sign in to the same account on both ends, then click <strong>Enter Desktop</strong> on the controller</td></tr><tr><td>Your own computer, even when it is powered off</td><td>Set up remote wake-up first: network adapter, motherboard and a helper device on the LAN; you need all three</td></tr><tr><td>The controlled computer is a Mac</td><td>First turn on <strong>允许本设备被控</strong> (Allow this device to be controlled) and two system permissions on the Mac</td></tr><tr><td>Checking a coding agent&#39;s progress from your phone while you are out</td><td>Same-account remote control: open <strong>Device Details</strong> &gt; <strong>Terminal</strong>, or use the full-screen desktop with mini window mode</td></tr><tr><td>You only want to fetch one file</td><td>Same account: use the <strong>File Transfer</strong> entry; remote assistance: use drag and drop or copy and paste</td></tr><tr><td>Operating in a meeting room or a café</td><td>Turn on <strong>Host Privacy Mode</strong> and <strong>Lock Controlled Device After Remote Session Ends</strong></td></tr><tr><td>Cannot connect on a company or school network</td><td>In the client, <strong>Settings</strong> &gt; <strong>Network</strong> &gt; <strong>Proxy Settings</strong>; this assumes you already have a working proxy</td></tr><tr><td>You want 4K, 144 fps, True Color, HDR, or several screens controlling several screens</td><td>These are VIP benefits; the official announcement says they go live on 2026-12-01</td></tr><tr><td>You want to show an Android phone&#39;s screen to someone</td><td>Android screen sharing; the viewer can only watch, not control</td></tr><tr><td>You would rather set up your own network and install one fewer remote control client</td><td>See the <a href="./../tailscale/">Tailscale</a> page</td></tr></tbody></table><h2 id="how-to-read-this-directory" tabindex="-1">How to read this directory <a class="header-anchor" href="#how-to-read-this-directory" aria-label="Permalink to &quot;How to read this directory&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Order</th><th>What to read</th><th>Goal</th></tr></thead><tbody><tr><td>1</td><td>The tutorial&#39;s &quot;Core concepts&quot;</td><td>Tell the controller, the controlled computer, the device ID and the verification code apart</td></tr><tr><td>2</td><td>The tutorial&#39;s &quot;Install&quot; and &quot;First task in 10 minutes&quot;</td><td>Connect once with a device ID and a verification code</td></tr><tr><td>3</td><td>The tutorial&#39;s &quot;Daily use&quot;</td><td>Set up unattended access, remote wake-up, file transfer and privacy mode</td></tr><tr><td>4</td><td>The tutorial&#39;s &quot;Pricing&quot; and &quot;Security and privacy essentials&quot;</td><td>Know where the free version ends, and know what you must not give out</td></tr><tr><td>5</td><td>The tutorial&#39;s &quot;Real-world use cases&quot;</td><td>Use the home computer as a remote workstation</td></tr></tbody></table><p>Read Core concepts before you touch anything. If you skip it and connect directly, you will get stuck on &quot;which end a switch is configured on&quot;.</p><h2 id="official-resources" tabindex="-1">Official resources <a class="header-anchor" href="#official-resources" aria-label="Permalink to &quot;Official resources&quot;">​</a></h2><ul><li><a href="https://uuyc.163.com/" target="_blank" rel="noreferrer">Official home page</a>: product positioning, entry points to the features, security statement.</li><li><a href="https://uuyc.163.com/download/" target="_blank" rel="noreferrer">Download page</a>: system requirements and current versions of the five clients.</li><li><a href="https://uuyc.163.com/help/" target="_blank" rel="noreferrer">Help center</a>: the directory of all feature guides and FAQs.</li><li><a href="https://uuyc.163.com/features/support/" target="_blank" rel="noreferrer">Remote assistance feature page</a>: remote assistance in three steps, and three platforms for the controlled computer.</li><li><a href="https://uuyc.163.com/help/20241204/40220_1197664.html" target="_blank" rel="noreferrer">How to remotely assist another computer</a>: the most complete explanation of verification codes, verification methods and favorite devices.</li><li><a href="https://uuyc.163.com/help/4.0wol.html" target="_blank" rel="noreferrer">How to set up remote wake-up</a>: wake-up conditions and step-by-step configuration.</li><li><a href="https://uuyc.163.com/help/20241210/40220_1199229.html" target="_blank" rel="noreferrer">How to transfer files</a>: where each of the three transfer methods applies.</li><li><a href="https://uuyc.163.com/help/20241203_40221_1197692.html" target="_blank" rel="noreferrer">How to turn privacy mode on or off</a>: the difference between the two privacy levels.</li><li><a href="https://uuyc.163.com/help/errorcode.html" target="_blank" rel="noreferrer">Error code solutions</a>: look here when you cannot connect or install.</li><li><a href="https://uuyc.163.com/help/membership.html" target="_blank" rel="noreferrer">Membership benefits</a>: benefit comparison of the free version, VIP and Global VIP.</li><li><a href="https://uuyc.163.com/bounty/" target="_blank" rel="noreferrer">Bounty hunter program</a>: the official channel for reporting vulnerabilities and getting rewards.</li><li><a href="https://uuyc.163.com/llms.txt" target="_blank" rel="noreferrer">llms.txt</a>: the official summary of product facts for AI and search engines; it lists every official page entry.</li></ul><h2 id="related-pages" tabindex="-1">Related pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related pages&quot;">​</a></h2><ul><li><a href="./uu-remote.html">Tutorial</a>: the only tutorial page in this directory, from installation to daily use.</li><li><a href="./../tailscale/">Tailscale</a>: compares two remote approaches, &quot;hole punching at the network layer&quot; and &quot;screen streaming&quot;.</li><li><a href="./../cindy/">Cindy</a>: built-in phone remote desktop feature.</li><li><a href="./../t3code/">T3 Code</a>: approve an agent&#39;s next step from your phone.</li><li><a href="./../codex/">Codex</a>: one of the coding agents that run on a remote dev machine.</li><li><a href="./../claude/">Claude</a>: same as above.</li></ul>',28)])])}const y=e(n,[["render",i]]);export{g as __pageData,y as default};
